function features(s,enemy={}){let keys=Object.entries(s).map(([r,c])=>`${r}:${c}`).sort(),f=keys.map(k=>'c|'+k);for(let i=0;i<keys.length;i++)for(let j=i+1;j<keys.length;j++)f.push(`p|${keys[i]}|${keys[j]}`);let ek=Object.entries(enemy).map(([r,c])=>`${r}:${c}`).sort();for(const e of ek)f.push('e|'+e);for(const a of keys)for(const e of ek)f.push('m|'+a+'|'+e);for(let i=0;i<ek.length;i++)for(let j=i+1;j<ek.length;j++)f.push('q|'+ek[i]+'|'+ek[j]);if(tier){f.push('t|'+tier);for(const a of keys)f.push('tc|'+tier+'|'+a)}return f}
function probability(model,s,enemy={},includeUnknown=true){const hypotheses=includeUnknown?opponentHypotheses(model,enemy):[{selection:enemy,weight:1}];let result=0;for(const h of hypotheses){let z=model.intercept;for(const f of features(s,h.selection))z+=model.weights[f]||0;result+=h.weight/(1+Math.exp(-z))}return result}
